import { ComponentPropsWithoutRef, CSSProperties, FC } from "react";

export const AnimatedShinyText = ({
  children,
  className,
  shimmerWidth = 100,
  ...props
}) => {
  return (
    <span
      style={
        {
          "--shiny-width": `${shimmerWidth}px`,
        }
      }
      className={`mx-auto max-w-md text-lime-400 shiny-text bg-clip-text bg-no-repeat [background-position:0_0] [background-size:var(--shiny-width)_100%] [transition:background-position_1s_cubic-bezier(.6,.6,0,1)_infinite] gradient bg-gradient-to-r from-white from-10% via-black to-90% to-white font-bold`}
    >
      {children}
    </span>
  );
};
