import { useState } from "react";
import {
  Dialog,
  DialogBackdrop,
  DialogPanel,
  DialogTitle,
} from "@headlessui/react";
import { motion } from "motion/react";

export const FormModal = ({
  open,
  onClose,
  fields = [],
  heading = "",
  subheading = "",
  closing_heading = "",
  closing_message = "",
  onSubmit,
  loading = false,
  submitted = false,
}) => {
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});

  if (!open) return null;

  const handleChange = (name, value, type) => {
    if (type === "checkbox") {
      setForm((prev) => ({
        ...prev,
        [name]: prev[name]
          ? prev[name].includes(value)
            ? prev[name].filter((v) => v !== value)
            : [...prev[name], value]
          : [value],
      }));
    } else {
      setForm((prev) => ({ ...prev, [name]: value }));
    }
  };

  const validate = () => {
    const errs = {};
    fields.forEach((f) => {
      if (f.required && !form[f.name]) {
        errs[f.name] = "Required";
      }
    });
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!validate()) return;
    onSubmit(form);
  };

  return (
    <Dialog className="relative z-50" open={open} onClose={onClose}>
      <DialogBackdrop className="fixed inset-0 bg-gray-950/90" />
      <div className="fixed inset-0 flex items-center justify-center ">
        <DialogPanel className="bg-lime-950 border border-lime-500/70 rounded-b-lg max-w-lg w-full mx-auto shadow-[0_0_20px] shadow-lime-400/50">
          <DialogTitle
            as="h2"
            className="text-lg py-4 px-10 text-center border-b bg-gray-950 border-lime-500/40 font-bold leading-6 text-lime-500"
          >
            {heading}
          </DialogTitle>
          {!submitted ? (
            <motion.div
              className="px-10 pb-6 pt-4 text-lime-500 space-y-4"
              initial={{ opacity: 0 }}
              whileInView={{ opacity: 1 }}
              transition={{ duration: 0.8, ease: "easeInOut" }}
            >
              {subheading && <p className="mb-4 text-lime-300">{subheading}</p>}
              <form onSubmit={handleSubmit} className="space-y-4">
                {fields.map((field) => (
                  <div key={field.name}>
                    <label className="block text-lime-400 font-medium mb-1">
                      {field.label}
                      {field.required && <span className="text-red-400 ml-1">*</span>}
                    </label>
                    {field.type === "text" && (
                      <input
                        type="text"
                        className="bg-gray-900 border border-lime-400/30 text-lime-400 text-md rounded-md placeholder:text-lime-400/50 focus:outline-none focus:ring focus:ring-lime-400/70 block w-full p-2.5"
                        value={form[field.name] || ""}
                        onChange={(e) => handleChange(field.name, e.target.value)}
                        placeholder={field.placeholder || ""}
                      />
                    )}
                    {field.type === "select" && (
                      <select
                        className="bg-gray-900 border border-lime-400/30 text-lime-400 text-md rounded-md focus:outline-none focus:ring focus:ring-lime-400/70 block w-full p-2.5"
                        value={form[field.name] || ""}
                        onChange={(e) => handleChange(field.name, e.target.value)}
                      >
                        <option value="">Select...</option>
                        {field.options.map((opt) => (
                          <option key={opt} value={opt}>
                            {opt}
                          </option>
                        ))}
                      </select>
                    )}
                    {field.type === "checkbox" && (
                      <div className="flex flex-wrap gap-3">
                        {field.options.map((opt) => (
                          <label key={opt} className="flex items-center gap-1">
                            <input
                              type="checkbox"
                              checked={form[field.name]?.includes(opt) || false}
                              onChange={() => handleChange(field.name, opt, "checkbox")}
                            />
                            <span>{opt}</span>
                          </label>
                        ))}
                      </div>
                    )}
                    {field.type === "radio" && (
                      <div className="flex gap-4">
                        {field.options.map((opt) => (
                          <label key={opt} className="flex items-center gap-1">
                            <input
                              type="radio"
                              name={field.name}
                              value={opt}
                              checked={form[field.name] === opt}
                              onChange={() => handleChange(field.name, opt)}
                            />
                            <span>{opt}</span>
                          </label>
                        ))}
                      </div>
                    )}
                    {errors[field.name] && (
                      <div className="text-red-400 text-sm mt-1">{errors[field.name]}</div>
                    )}
                  </div>
                ))}
                <div className="mt-6 flex justify-end">
                  <button
                    type="button"
                    onClick={onClose}
                    className="px-4 py-2 border border-lime-500 text-lime-300 rounded-md font-medium cursor-pointer mr-2"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="inline-flex justify-center px-4 py-2 border border-transparent rounded-md text-base font-semibold text-gray-900 bg-lime-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-lime-500 cursor-pointer"
                    disabled={loading}
                  >
                    {loading ? "Submitting..." : "Submit"}
                  </button>
                </div>
              </form>
            </motion.div>
          ) : (
            <div className="px-10 pb-6 pt-4 text-lime-500 space-y-4 text-center">
              {closing_heading && (
                <h2 className="text-xl font-bold text-lime-400 mb-2">{closing_heading}</h2>
              )}
              {closing_message && (
                <p className="text-lime-300 text-base">{closing_message}</p>
              )}
            </div>
          )}
        </DialogPanel>
      </div>
    </Dialog>
  );
};

export default FormModal;