import { ChevronDownIcon } from "@heroicons/react/24/outline";
import { useState } from "react";

function AccordionElement({ title, children }) {
  const [isOpen, setState] = useState(false);
  const handleClick = () => {
    setState(!isOpen);
  };
  return (
    <div
      onClick={() => handleClick()}
      className={` bg-lime-950/70 border overflow-y-clip border-lime-400/60 rounded-xl align-middle shadow-lg shadow-black/50 my-2 md:my-4 lg:my-6`}
    >
      <div className={`flex  py-1 px-2 lg:py-2 lg:px-4 justify-between items-center text-xl`}>
        <h2 className="text-lg text-lime-400 mt-2 mx-2">
          {title}
        </h2>
        <ChevronDownIcon
          className={`mt-2 text-lg text-lime-400 transition-transform duration-300 w-6 h-6 ${
            isOpen ? "rotate-180 " : " hover:text-lime-400/40"
          }`}
        ></ChevronDownIcon>
      </div>
      <div
        className={`bg-lime-950/40 px-4  lg:px-6 rounded-b-xl text-justify transition-all duration-800 ease-in-out text-slate-900 mb-2 w-full text-lg sm:text-xl md:text-2xl ${
          isOpen
            ? " py-1 lg:py-2 max-h-max overflow-auto"
            : "max-h-0 overflow-hidden"
        }`}
      >
        {children}
      </div>
    </div>
  );
}

export default AccordionElement;
