import LandingPage from './components/LandingPage'
import {BrowserRouter as Router, Route, Routes} from 'react-router-dom'
import InterviewPage from './components/InterviewPage'
import FeedbackPage from './components/FeedbackPage'
import LoginPage from './components/auth/LoginPage'
import RegisterPage from './components/auth/RegisterPage'
import HomePage from './components/dashboard/HomePage'
import ProtectedRoute from './components/auth/ProtectedRoute'
import PricingPage from './components/PricingPage'
import TermsAndConditions from './components/legal/TermsAndConditions'

function App() {
  const baseUrl = process.env.REACT_APP_BASE_URL || '';
  return (
    <Router>
      <Routes>
        <Route path={`${baseUrl}/about`} element={<LandingPage />} caseSensitive={false} />
        <Route path={`${baseUrl}/terms`} element={<TermsAndConditions />} caseSensitive={false} />
        <Route path={`${baseUrl}/login`} element={<LoginPage />} caseSensitive={false} />
        <Route path={`${baseUrl}/register`} element={<RegisterPage />} caseSensitive={false} />
        <Route path={`${baseUrl}/interview`} element={<ProtectedRoute>
  {(user) => <InterviewPage user={user} credits={user.credits} />}
</ProtectedRoute>} caseSensitive={false} />
        <Route path={`${baseUrl}/feedback`} element={<ProtectedRoute><FeedbackPage /></ProtectedRoute>} caseSensitive={false} />
        <Route path={`${baseUrl}/`} element={<ProtectedRoute><HomePage /></ProtectedRoute>} caseSensitive={false} />
        <Route path={`${baseUrl}/pricing`} element={<PricingPage />} caseSensitive={false} />
      </Routes>
    </Router>
  )
}

export default App
