import { useEffect, useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";

const LoginPage = () => {
  
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: "", password: "" });
  const [msg, setMsg] = useState({ type: "", message: "" });
  const API_URL = process.env.REACT_APP_API_BASE_URL;
  const CLIENT_BASE_URL = process.env.REACT_APP_BASE_URL || "";
  const [searchParams] = useSearchParams();
  const token = searchParams.get("token");
  const next = searchParams.get("next");

  const handleChange = (e) => {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  useEffect(() => {
    const verifyEmail = async () => {
      if (!token) return;
      try {
        const res = await fetch(`${API_URL}/verify-email/${token}`);
        const data = await res.json();
        if (res.ok) {
          setMsg({
            type: "success",
            message: "Email verified successfully! Please log in.",
          });
          navigate(`${CLIENT_BASE_URL}/login`, { replace: true });
        } else {
          setMsg({
            type: "error",
            message: `Verification failed: ${data.error || "Unknown error"}`,
          });
        }
      } catch (err) {
        console.error("Verification error:", err);
        setMsg({
          type: "error",
          message: "Verification failed. Please try again.",
        });
      }
    };
    verifyEmail();
  }, [token]);
  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg({ type: "", message: "" });
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(form),
      });

      const data = await res.json();
      if (!res.ok) {
        setMsg({
          type: "error",
          message: data.msg || "Login failed. Please try again.",
        });
        return; // Stop further execution if login fails
      }
      if (next) {
        navigate(`${CLIENT_BASE_URL}/${next}`, { replace: true });
      } else {
        navigate(`${CLIENT_BASE_URL}/`); // or /dashboard etc.
      }
    } catch (err) {
      setMsg({ type: "error", message: 'An error occurred. Please try again later.' });
    }
  };
  return (
    <section className="bg-gray-950">
      <div className="flex flex-col items-center justify-center px-6 py-8 mx-auto md:h-screen lg:py-0">
        <a
          className="  bg-clip-text text-2xl font-extrabold text-transparent px-1 py-1 mb-4 rounded-full tracking-wide bg-gradient-to-r from-lime-400 to-95% to-lime-500"
          href="#"
        >
          ReflectlyAI
        </a>
        <div className="w-full bg-lime-950 border border-lime-500/70 rounded-b-lg mx-auto shadow-[0_0_20px] shadow-lime-400/50 md:mt-0 sm:max-w-md xl:p-0">
          <div className="p-6 space-y-4 md:space-y-6 sm:p-8">
            <h1 className="text-xl font-bold leading-tight tracking-tight text-center md:text-2xl text-lime-500">
              Sign in to your account
            </h1>
            <form
              onSubmit={handleSubmit}
              className="space-y-4 md:space-y-6"
              action="#"
            >
              <div>
                <label
                  for="email"
                  className="block mt-4 mb-2 text-base font-medium text-lime-500"
                >
                  Your email
                </label>
                <input
                  type="text"
                  name="email"
                  id="email"
                  onChange={handleChange}
                  className="bg-gray-900 border placeholder:text-lime-700 border-lime-400/30 text-lime-400 autofill:bg-gray-900 autofill:text-lime-400 text-md rounded-md focus:outline-none focus:ring focus:ring-lime-400/70 block w-full p-2.5"
                  placeholder="Enter your email"
                  required=""
                />
              </div>
              <div>
                <label
                  for="password"
                  className="block mt-4 mb-2 text-base font-medium text-lime-500"
                >
                  Password
                </label>
                <input
                  type="password"
                  name="password"
                  id="password"
                  placeholder="••••••••"
                  onChange={handleChange}
                  className="bg-gray-900 border placeholder:text-lime-700 border-lime-400/30 text-lime-400 text-md rounded-md focus:outline-none focus:ring focus:ring-lime-400/70 block w-full p-2.5"
                  required=""
                />
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-start align-middle">
                  <div className="flex items-center h-5">
                    <input
                      type="checkbox"
                      className="w-4 h-4 text-lime-400 border border-lime-400 bg-gray-900 rounded-sm"
                      required=""
                    />
                  </div>
                  <div className="ml-3 text-sm">
                    <label for="remember" className="text-lime-400">
                      Remember me
                    </label>
                  </div>
                </div>
                {/* <a
                  href="#"
                  className="text-sm font-medium text-lime-400 hover:underline"
                >
                  Forgot password?
                </a> */}
              </div>
              {msg.message && (
                <p
                  className={`text-base font-medium text-center ${
                    msg.type === "error" ? "text-red-400" : "text-lime-400"
                  }`}
                >
                  {msg.message}
                </p>
              )}
              <button
                type="submit"
                className="w-2/3 block mx-auto px-4 py-2 border border-lime-500 text-lime-300 rounded-md font-medium cursor-pointer focus:ring-4 focus:outline-none focus:ring-primary-300 text-base text-center"
              >
                Sign in
              </button>
              <p className="text-sm font-light text-lime-500">
                Don’t have an account yet?{" "}
                <Link
                  to={`${CLIENT_BASE_URL}/register`}
                  className="font-semibold tracking-wide text-lime-400 underline"
                >
                  Register
                </Link>
              </p>
            </form>
          </div>
        </div>
      </div>
    </section>
  );
};

export default LoginPage;
