import React from "react";

const Skeleton = ({isReversed = false}) => {
  return (
    <div
      role="status"
      class={`flex gap-3 ${isReversed ? "flex-col-reverse" : "flex-col"} pulse-animation w-full max-w-lg sm:max-w-2xl lg:max-w-3xl`}
    >
      <div class="flex items-center w-full mx-auto">
        <div class="h-3 bg-gray-400 rounded-full w-1/4"></div>
        <div class="h-3 ms-2 bg-gray-600 rounded-full w-1/2"></div>
        <div class="h-3 ms-2 bg-gray-600 rounded-full w-1/4"></div>
      </div>
      <div class="flex items-center w-full mx-auto">
        <div class="h-3 bg-gray-500 rounded-full w-[40%]"></div>
        <div class="h-3 ms-2 bg-gray-700 rounded-full w-[50%]"></div>
        <div class="h-3 ms-2 bg-gray-400 rounded-full w-[10%]"></div>
      </div>
      <div class="flex items-center w-full mx-auto">
        <div class="h-3 rounded-full bg-gray-700 w-[20%]"></div>
        <div class="h-3 ms-2 bg-gray-500 rounded-full w-[40%]"></div>
        <div class="h-3 ms-2 bg-gray-600 rounded-full w-[40%]"></div>
      </div>

      <div class="flex items-center w-full mx-auto">
        <div class="h-3 bg-gray-500 rounded-full w-[40%]"></div>
        <div class="h-3 ms-2 bg-gray-700 rounded-full w-[40%]"></div>
        <div class="h-3 ms-2 bg-gray-600 rounded-full w-[20%]"></div>
      </div>
      <div class="flex items-center w-full mx-auto">
        <div class="h-3 bg-lime-700 rounded-full w-[25%]"></div>
        <div class="h-3 ms-2 bg-lime-800 rounded-full w-[50%]"></div>
        <div class="h-3 ms-2 bg-lime-900 rounded-full w-[25%]"></div>
      </div>
      <div class="flex items-center w-full mx-auto">
        <div class="h-3 bg-lime-800 rounded-full w-[40%]"></div>
        <div class="h-3 ms-2 rounded-full bg-lime-900 w-[30%]"></div>
        <div class="h-3 ms-2 rounded-full bg-lime-950 w-[30%]"></div>
      </div>
      <span class="sr-only">Loading...</span>
    </div>
  );
};

export default Skeleton;
